import {state,save,esc,dateKey} from '../../lib/store.js';
import {button,badge,empty} from '../pixel/primitives.js';
import {randomExcerpt} from '../../lib/training-text.js';
export const liveNews={data:null,loading:false,error:'',attempt:0,day:'',staticMode:false};
function hasLocalNewsBackend(){return !document.querySelector('meta[name="app-hosting"][content="static-pages"]')}
function requestSignal(ms=15000){if(typeof globalThis.AbortSignal?.timeout==='function')return globalThis.AbortSignal.timeout(ms);const controller=new AbortController();setTimeout(()=>controller.abort(),ms);return controller.signal}
function newsURL(local,force){if(local)return '/api/news'+(force?'?refresh=1':'');const url=new URL('../../data/news.json',import.meta.url);if(force)url.searchParams.set('refresh',Date.now());return url.href}
export async function loadNews(force=false){const local=hasLocalNewsBackend();if(liveNews.loading||!force&&liveNews.day===dateKey()&&Date.now()-liveNews.attempt<45*60000)return false;liveNews.staticMode=!local;liveNews.loading=true;liveNews.attempt=Date.now();liveNews.day=dateKey();liveNews.error='';try{const response=await fetch(newsURL(local,force),{signal:requestSignal(),cache:force?'no-store':'default'});if(!response.ok)throw Error('HTTP '+response.status);const data=await response.json();if(!data||!Array.isArray(data.articles)||!Array.isArray(data.sources))throw Error('Invalid news data');liveNews.data=data}catch{liveNews.error='NEWS FEED TEMPORARILY UNAVAILABLE';if(!liveNews.data)liveNews.data={articles:[],sources:[],checkedAt:null,mode:local?'live-rss':'static-rss'}}finally{liveNews.loading=false}return true}
export function selectedArticle(){return state.selectedNews?.date===dateKey()?state.selectedNews.article:null}
export function chooseArticle(id){const article=liveNews.data?.articles.find(a=>a.id===id);if(!article)return;state.selectedNews={date:dateKey(),article:{...article,articleId:article.id}};ensureExcerpt(true);save()}
export function ensureExcerpt(force=false){const a=selectedArticle();if(!a)return null;if(force||state.newsExercise?.date!==dateKey()||state.newsExercise?.articleId!==a.id){const next=randomExcerpt(a.availableText,state.newsExercise?.excerpt);if(next.text===state.newsExercise?.excerpt&&state.newsExercise?.articleId===a.id&&state.newsExercise?.date===dateKey())return state.newsExercise;state.newsExercise={date:dateKey(),articleId:a.id,excerpt:next.text,count:next.count,draftKey:'news-'+a.id+'-'+Date.now()};save()}return state.newsExercise}
export function newsView(ui){const data=liveNews.data;let articles=(data?.articles||[]).filter(a=>!ui.newsCategory||a.category===ui.newsCategory);const today=articles.filter(a=>dateKey(a.publishedAt)===dateKey());let windowLabel='TODAY';if(today.length)articles=today;else{const recent=articles.filter(a=>Date.now()-Date.parse(a.publishedAt)<=48*3600000);articles=recent.length?recent:articles;windowLabel=recent.length?'PAST 48 HOURS':'PAST 72 HOURS'}const a=selectedArticle(),emptyMessage=liveNews.loading||!liveNews.attempt?'正在读取官方 RSS…':liveNews.error?'NEWS FEED TEMPORARILY UNAVAILABLE':'此分类最近 72 小时暂无可用新闻。可以切换分类或稍后刷新。';return `<div class="row wrap mb"><div>${badge('OFFICIAL RSS / FREE','cyan')} <span class="micro muted">${liveNews.staticMode?'STATIC RSS SNAPSHOT':'45 MIN CACHE'} · ${windowLabel}</span></div>${button(liveNews.loading?'LOADING…':liveNews.error?'RETRY':'REFRESH NEWS','news-refresh',liveNews.loading?'disabled':'')}</div><div class="actions mb">${['','Política','Economia','Sociedade'].map(c=>button(c||'ALL','news-filter',`data-value="${c}"`,ui.newsCategory===c?'primary':'')).join('')}</div><div class="news-sources">${(data?.sources||[]).map(s=>`<span class="micro ${s.status==='ok'?'muted':'warning'}">${esc(s.label)} · ${s.status==='ok'?'ONLINE':s.status==='stale'?'CACHED / SOURCE UNAVAILABLE':'SOURCE TEMPORARILY UNAVAILABLE'} ${esc(s.error)}</span>`).join('')}</div>${liveNews.error?`<div class="notice">${esc(liveNews.error)}${data?.articles?.length?' · 保留上次读取的真实新闻，日期不变。':''}</div>`:''}${a?`<div class="notice">TODAY'S SELECTED ARTICLE · ${esc(a.title)}</div>`:''}<p class="small muted">只展示媒体 RSS 提供的文本。READ 打开原站；训练不抓取付费全文。更新时间：${data?.checkedAt?new Date(data.checkedAt).toLocaleString():'等待连接'}。</p><div class="live-news-grid">${articles.map(n=>`<article class="panel news-item"><div class="row wrap">${badge(n.category,'magenta')}<span class="micro">${esc(n.source)}</span></div><h3 lang="pt">${esc(n.title)}</h3><p class="micro muted">${dateKey(n.publishedAt)===dateKey()?'Today · ':dateKey(n.publishedAt)===dateKey(new Date().setDate(new Date().getDate()-1))?'Yesterday · ':''}${esc(new Date(n.publishedAt).toLocaleString())}</p><p lang="pt">${esc(n.description||'此条 RSS 未提供摘要。')}</p><div class="actions"><a class="button" href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">READ ↗</a>${button(a?.id===n.id?'SELECTED / TRAIN':'USE FOR TRAINING','news-select',`data-id="${esc(n.id)}" ${!n.availableText?'disabled title="RSS 未提供可训练文本"':''}`,'primary')}</div></article>`).join('')||empty(emptyMessage)}</div>`}
